// Uploaded files live on a persistent volume (DATA_DIR). Keys are generated by the
// server (never from user input) so paths cannot escape the uploads folder.
import fs from "node:fs";
import fsp from "node:fs/promises";
import path from "node:path";
import { randomUUID } from "node:crypto";
import { env } from "../env";

const root = path.resolve(env.DATA_DIR, "uploads");

export function ensureStorage() {
  fs.mkdirSync(root, { recursive: true });
}

const SAFE_EXT = /^[a-z0-9]{1,8}$/;

/** New storage key like `activities/<activityId>/<uuid>.pdf`. */
export function newKey(scope: "activities" | "library" | "tmp" | "requests", ownerId: string, ext: string): string {
  if (!/^[0-9a-f-]{36}$/.test(ownerId)) throw new Error("invalid owner id");
  const e = SAFE_EXT.test(ext) ? `.${ext}` : "";
  return `${scope}/${ownerId}/${randomUUID()}${e}`;
}

function resolveKey(key: string): string {
  const full = path.resolve(root, key);
  if (!full.startsWith(root + path.sep)) throw new Error("invalid storage key");
  return full;
}

export async function saveFile(key: string, data: Uint8Array): Promise<void> {
  const full = resolveKey(key);
  await fsp.mkdir(path.dirname(full), { recursive: true });
  const tmp = `${full}.part`;
  await fsp.writeFile(tmp, data);
  await fsp.rename(tmp, full);
}

export async function readFile(key: string): Promise<Buffer> {
  return fsp.readFile(resolveKey(key));
}

/** Read stream for a stored file; `range` is inclusive (as in HTTP Range requests). */
export function fileStream(key: string, range?: { start: number; end: number }): fs.ReadStream {
  return fs.createReadStream(resolveKey(key), range);
}

export async function fileSize(key: string): Promise<number | null> {
  try {
    return (await fsp.stat(resolveKey(key))).size;
  } catch {
    return null;
  }
}

export async function copyFile(fromKey: string, toKey: string): Promise<void> {
  const to = resolveKey(toKey);
  await fsp.mkdir(path.dirname(to), { recursive: true });
  await fsp.copyFile(resolveKey(fromKey), to);
}

export async function deleteFile(key: string | null | undefined): Promise<void> {
  if (!key) return;
  await fsp.rm(resolveKey(key), { force: true });
}

/** Removes a whole folder such as `activities/<id>` (after the DB rows are gone). */
export async function deletePrefix(prefix: string): Promise<void> {
  const full = resolveKey(prefix);
  await fsp.rm(full, { recursive: true, force: true });
}
